args.query:
WITH active_studies AS (
    SELECT * FROM studies WHERE status = 'active' ORDER BY study_id
)
SELECT json_group_array(
    json_object(
        'study_id', study_id,
        'title', title,
        'owner', owner,
        'start_date', start_date,
        'status', status,
        'notes', COALESCE(notes, '')
    )
) FROM active_studies;

